 "content": "from collections import Counter

def transform(grid):
    """Shift the non-background pattern down one row."""
    if not grid:
        return []
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    return [[background for _ in grid[0]]] + [row[:] for row in grid[:-1]]
